import React from 'react';
import Slider from 'react-slick';
import { Box, Button } from '@mui/material';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

// Slider İçeriği
const slides = [
  {
    id: 1,
    image: "https://cdn.gcp.techcareer.net/luxoft_hackathon_318x367_ac5dacfbee/luxoft_hackathon_318x367_ac5dacfbee.png",
    alt: "Luxoft Parking Hackathon",
    link: "https://www.techcareer.net/hackathon/luxoft-parking-hackathon",
  },
  {
    id: 2,
    image: "https://cdn.gcp.techcareer.net/2024_duyurular_318x367_f5da06e5fe/2024_duyurular_318x367_f5da06e5fe.png",
    alt: "TechReport 2024 Yazılımcı Anketi",
    link: "https://survey.alchemer.com/s3/8068418/N240021",
  },
  {
    id: 3,
    image: "https://cdn.gcp.techcareer.net/TR_318x367_f550f349b5/TR_318x367_f550f349b5.png",
    alt: "Teknoloji Terimleri Rehberi",
    link: "https://event.kariyer.net/sLIcnw",
  },
  {
    id: 4,
    image: "https://cdn.gcp.techcareer.net/Banner_TR_318x367_1_3d940b6d36/Banner_TR_318x367_1_3d940b6d36.png",
    alt: "Techcareer.net Ücretsiz Eğitimler",
    link: "https://www.techcareer.net/courses",
  },
  {
    id: 5,
    image: "https://cdn.gcp.techcareer.net/318x367_ae2bb8b030/318x367_ae2bb8b030.png",
    alt: "Hayalindeki İş Fırsatları",
    link: "https://www.techcareer.net/jobs",
  },
  {
    id: 6,
    image: "https://cdn.gcp.techcareer.net/senior_aday_tecrubeli_yazilimci_e9c7cf2c86/senior_aday_tecrubeli_yazilimci_e9c7cf2c86.png",
    alt: "Senior Aday İş Fırsatları",
    link: "https://go.techcareer.net/UVp19j",
  },
];

const TechCareerSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 5000,
    arrows: true,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
        },
      },
    ],
  };

  return (
    <Box sx={{ backgroundColor: '#F5F9FF', py: 4 }}>
      <Slider {...settings}>
        {slides.map((slide) => (
          <Box key={slide.id} sx={{ px: 2, textAlign: 'center' }}>
            <Button
              href={slide.link}
              sx={{
                p: 0,
                display: 'block',
                textDecoration: 'none',
                '&:hover': {
                  transform: 'scale(1.05)',
                  transition: 'transform 0.3s ease',
                },
              }}
            >
              <Box
                component="img"
                src={slide.image}
                alt={slide.alt}
                sx={{
                  width: '100%',
                  height: 'auto',
                  maxWidth: '250px',
                  mx: 'auto',
                  borderRadius: 2,
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                }}
              />
            </Button>
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default TechCareerSlider;
